using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class CandidateHomePage:UserControl{FlowLayoutPanel body;public CandidateHomePage(){Dock=DockStyle.Fill;BackColor=Theme.Background;AutoScroll=true;Padding=new Padding(20);body=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,WrapContents=true,FlowDirection=L.Fa?FlowDirection.RightToLeft:FlowDirection.LeftToRight,Padding=new Padding(4)};Controls.Add(body);Build();}void Build(){body.Controls.Clear();var welcome=Card(L.Fa?"مسیر شغلی شما":"Your career workspace",L.Fa?"فرصت‌های مناسب را ذخیره کنید، هشدار بسازید و روند درخواست‌ها را از یکجا دنبال کنید.":"Save relevant jobs, create alerts and follow your applications from one workspace.",760,116);body.Controls.Add(welcome);int saved=Convert.ToInt32(Database.Scalar("SELECT COUNT(*) FROM Favorites WHERE UserId=@u AND EntityType='Job'",new SqlParameter("@u",AppSession.UserId)));int alerts=Convert.ToInt32(Database.Scalar("SELECT COUNT(*) FROM JobAlerts WHERE UserId=@u AND IsActive=1",new SqlParameter("@u",AppSession.UserId)));int open=Convert.ToInt32(Database.Scalar("SELECT COUNT(*) FROM Jobs WHERE Status='Open'"));body.Controls.Add(Metric(L.Fa?"فرصت‌های باز":"Open jobs",open.ToString(),"▦"));body.Controls.Add(Metric(L.Fa?"ذخیره‌شده‌ها":"Saved jobs",saved.ToString(),"★"));body.Controls.Add(Metric(L.Fa?"هشدارهای فعال":"Active alerts",alerts.ToString(),"●"));var recent=Ui.Grid();recent.Width=760;recent.Height=260;recent.DataSource=Database.Query("SELECT TOP 8 j.Title,ISNULL(c.Name,'') Company,j.City,j.EmploymentType,j.CreatedAt FROM Jobs j LEFT JOIN Companies c ON c.Id=j.CompanyId WHERE j.Status='Open' ORDER BY j.CreatedAt DESC");var p=Ui.Card();p.Width=800;p.Height=320;p.Controls.Add(recent);var h=Ui.Label(L.Fa?"جدیدترین فرصت‌ها":"Latest opportunities",14,true);h.Dock=DockStyle.Top;h.Height=38;p.Controls.Add(h);body.Controls.Add(p);}Panel Metric(string t,string v,string icon){var p=Ui.Card();p.Width=240;p.Height=130;var a=Ui.Label(icon+"  "+t,10,true);a.Dock=DockStyle.Top;a.Height=34;var n=Ui.Label(v,25,true);n.ForeColor=Theme.Primary;n.Dock=DockStyle.Fill;n.TextAlign=ContentAlignment.MiddleCenter;p.Controls.Add(n);p.Controls.Add(a);return p;}Panel Card(string t,string s,int w,int h){var p=Ui.Card();p.Width=w;p.Height=h;var a=Ui.Label(t,17,true);a.Dock=DockStyle.Top;a.Height=42;var b=Ui.Label(s,10);b.ForeColor=Theme.Muted;b.Dock=DockStyle.Fill;b.MaximumSize=new Size(w-40,0);p.Controls.Add(b);p.Controls.Add(a);return p;}}}
